const std = @import("std");
const mem = std.mem;
const math = std.math;
const rand = std.rand;
const atomic = std.atomic;
const time = std.time;
const Allocator = mem.Allocator;
const ArrayList = std.ArrayList;
const HashMap = std.HashMap;
const DefaultPrng = rand.DefaultPrng;
const c = @cImport({
    @cInclude("math.h");
    @cInclude("complex.h");
    @cInclude("fftw3.h");
});

pub const TensorShape = struct {
    dims: []usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, dims: []const usize) !TensorShape {
        var self_dims = try allocator.alloc(usize, dims.len);
        @memcpy(self_dims, dims);
        return TensorShape{
            .dims = self_dims,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *TensorShape) void {
        self.allocator.free(self.dims);
    }

    pub fn total_elements(self: *const TensorShape) usize {
        var total: usize = 1;
        for (self.dims) |dim| {
            if (dim == 0) return 0;
            total = math.mul(usize, total, dim) catch return math.maxInt(usize);
        }
        return total;
    }

    pub fn equals(self: *const TensorShape, other: *const TensorShape) bool {
        if (self.dims.len != other.dims.len) return false;
        for (self.dims, other.dims) |d1, d2| {
            if (d1 != d2) return false;
        }
        return true;
    }

    pub fn dupe(self: *const TensorShape) !TensorShape {
        return try init(self.allocator, self.dims);
    }

    pub fn broadcast(self: *const TensorShape, other: *const TensorShape) !TensorShape {
        const max_len = math.max(self.dims.len, other.dims.len);
        var new_dims = try self.allocator.alloc(usize, max_len);
        errdefer self.allocator.free(new_dims);
        var i: usize = 0;
        while (i < max_len) : (i += 1) {
            const d1 = if (self.dims.len > i) self.dims[self.dims.len - 1 - i] else 1;
            const d2 = if (other.dims.len > i) other.dims[other.dims.len - 1 - i] else 1;
            if (d1 == d2 or d1 == 1 or d2 == 1) {
                new_dims[max_len - 1 - i] = math.max(d1, d2);
            } else {
                return error.BroadcastError;
            }
        }
        return TensorShape{ .dims = new_dims, .allocator = self.allocator };
    }

    pub fn reshape(self: *const TensorShape, new_dims: []const usize) !TensorShape {
        const old_total = self.total_elements();
        var new_total: usize = 1;
        for (new_dims) |d| new_total *= d;
        if (old_total != new_total) return error.ReshapeSizeMismatch;
        return try init(self.allocator, new_dims);
    }

    pub fn stride(self: *const TensorShape) ![]usize {
        var strides = try self.allocator.alloc(usize, self.dims.len);
        var s: usize = 1;
        var i: isize = @intCast(self.dims.len - 1);
        while (i >= 0) : (i -= 1) {
            strides[@intCast(i)] = s;
            s *= self.dims[@intCast(i)];
        }
        return strides;
    }

    pub fn indexToCoords(self: *const TensorShape, index: usize) ![]usize {
        var coords = try self.allocator.alloc(usize, self.dims.len);
        var rem = index;
        var i: isize = @intCast(self.dims.len - 1);
        while (i >= 0) : (i -= 1) {
            const dim = self.dims[@intCast(i)];
            coords[@intCast(i)] = rem % dim;
            rem /= dim;
        }
        return coords;
    }
};

pub const DataType = enum {
    f32,
    f64,
    i32,
    u32,
    c64,
    bool,
};

pub const TensorData = union(DataType) {
    f32: []f32,
    f64: []f64,
    i32: []i32,
    u32: []u32,
    c64: []c.c64,
    bool: []bool,

    pub fn deinit(self: *TensorData, allocator: Allocator) void {
        switch (self.*) {
            inline else => |data| allocator.free(data),
        }
    }

    pub fn elementSize(self: TensorData) usize {
        return switch (self) {
            .f32, .i32, .u32, .bool => 4,
            .f64, .c64 => 8,
        };
    }

    pub fn copy(self: TensorData, allocator: Allocator) !TensorData {
        switch (self) {
            inline else => |data| {
                var new_data = try allocator.alloc(@TypeOf(data[0]), data.len);
                @memcpy(new_data, data);
                return @unionInit(TensorData, @tagName(self), new_data);
            },
        }
    }
};

pub const Tensor = struct {
    shape: TensorShape,
    data: TensorData,
    allocator: Allocator,
    dtype: DataType,
    strides: []usize,
    requires_grad: bool = false,
    grad: ?*Tensor = null,
    ref_count: atomic.Value(usize) = atomic.Value(usize).init(1),

    pub fn init(allocator: Allocator, dims: []const usize, dtype: DataType) !*Tensor {
        var shape = try TensorShape.init(allocator, dims);
        errdefer shape.deinit();
        var strides = try shape.stride();
        errdefer allocator.free(strides);
        const total = shape.total_elements();
        var data: TensorData = switch (dtype) {
            .f32 => .{ .f32 = try allocator.alloc(f32, total) },
            .f64 => .{ .f64 = try allocator.alloc(f64, total) },
            .i32 => .{ .i32 = try allocator.alloc(i32, total) },
            .u32 => .{ .u32 = try allocator.alloc(u32, total) },
            .c64 => .{ .c64 = try allocator.alloc(c.c64, total) },
            .bool => .{ .bool = try allocator.alloc(bool, total) },
        };
        errdefer data.deinit(allocator);
        var tensor = try allocator.create(Tensor);
        tensor.* = .{
            .shape = shape,
            .data = data,
            .allocator = allocator,
            .dtype = dtype,
            .strides = strides,
        };
        return tensor;
    }

    pub fn deinit(self: *Tensor) void {
        if (self.grad) |g| {
            g.deinit();
        }
        self.data.deinit(self.allocator);
        self.allocator.free(self.strides);
        self.shape.deinit();
        self.allocator.destroy(self);
    }

    pub fn retain(self: *Tensor) void {
        _ = self.ref_count.incr();
    }

    pub fn release(self: *Tensor) void {
        if (self.ref_count.decr() == 0) {
            self.deinit();
        }
    }

    pub fn zeros(allocator: Allocator, dims: []const usize, dtype: DataType) !*Tensor {
        var tensor = try init(allocator, dims, dtype);
        switch (tensor.data) {
            .f32 => @memset(tensor.data.f32, 0.0),
            .f64 => @memset(tensor.data.f64, 0.0),
            .i32 => @memset(tensor.data.i32, 0),
            .u32 => @memset(tensor.data.u32, 0),
            .c64 => @memset(tensor.data.c64, .{ .re = 0.0, .im = 0.0 }),
            .bool => @memset(tensor.data.bool, false),
        }
        return tensor;
    }

    pub fn ones(allocator: Allocator, dims: []const usize, dtype: DataType) !*Tensor {
        var tensor = try init(allocator, dims, dtype);
        switch (tensor.data) {
            .f32 => @memset(tensor.data.f32, 1.0),
            .f64 => @memset(tensor.data.f64, 1.0),
            .i32 => @memset(tensor.data.i32, 1),
            .u32 => @memset(tensor.data.u32, 1),
            .c64 => @memset(tensor.data.c64, .{ .re = 1.0, .im = 0.0 }),
            .bool => @memset(tensor.data.bool, true),
        }
        return tensor;
    }

    pub fn randomNormal(allocator: Allocator, dims: []const usize, dtype: DataType, mean: f64, stddev: f64, seed: u64) !*Tensor {
        var prng = DefaultPrng.init(seed);
        var random = prng.random();
        var tensor = try init(allocator, dims, dtype);
        switch (tensor.data) {
            .f32 => for (tensor.data.f32) |*val| {
                val.* = @floatCast(mean + stddev * random.floatNorm(f64));
            },
            .f64 => for (tensor.data.f64) |*val| {
                val.* = mean + stddev * random.floatNorm(f64);
            },
            else => return error.UnsupportedType,
        }
        return tensor;
    }

    pub fn copy(self: *Tensor) !*Tensor {
        var new_tensor = try init(self.allocator, self.shape.dims, self.dtype);
        switch (self.data) {
            inline else => |data, tag| @memcpy(@field(new_tensor.data, @tagName(tag)), data),
        }
        new_tensor.requires_grad = self.requires_grad;
        if (self.grad) |g| {
            new_tensor.grad = try g.copy();
        }
        return new_tensor;
    }

    fn getBroadcastIndex(self: *Tensor, global_i: usize, b_shape: *TensorShape) !usize {
        var coords = try b_shape.indexToCoords(global_i);
        defer self.allocator.free(coords);
        var idx: usize = 0;
        var offset = b_shape.dims.len - self.shape.dims.len;
        for (coords, 0..) |c, j| {
            var dim_idx = j - offset;
            if (dim_idx < 0) continue;
            var dim = self.shape.dims[dim_idx];
            var local_c = if (dim == 1) 0 else if (c >= dim) return error.OutOfBounds else c;
            idx += local_c * self.strides[dim_idx];
        }
        return idx;
    }

    pub fn add(self: *Tensor, other: *Tensor) !*Tensor {
        if (self.dtype != other.dtype) return error.TypeMismatch;
        var b_shape = try self.shape.broadcast(&other.shape);
        defer b_shape.deinit();
        var result = try init(self.allocator, b_shape.dims, self.dtype);
        const total = result.shape.total_elements();
        switch (self.dtype) {
            .f32 => {
                const a_data = self.data.f32;
                const b_data = other.data.f32;
                const c_data = result.data.f32;
                var i: usize = 0;
                while (i < total) : (i += 1) {
                    const idx_a = try self.getBroadcastIndex(i, &b_shape);
                    const idx_b = try other.getBroadcastIndex(i, &b_shape);
                    c_data[i] = a_data[idx_a] + b_data[idx_b];
                }
            },
            .f64 => {
                const a_data = self.data.f64;
                const b_data = other.data.f64;
                const c_data = result.data.f64;
                var i: usize = 0;
                while (i < total) : (i += 1) {
                    const idx_a = try self.getBroadcastIndex(i, &b_shape);
                    const idx_b = try other.getBroadcastIndex(i, &b_shape);
                    c_data[i] = a_data[idx_a] + b_data[idx_b];
                }
            },
            else => return error.NotImplemented,
        }
        return result;
    }

     pub fn addSelf(self: *Tensor, other: *Tensor) !void {
        if (self.dtype != other.dtype) return error.TypeMismatch;
