                var i: usize = 0;
                while (i < total) : (i += 1) {
                    const idx_a = try self.getBroadcastIndex(i, &b_shape);
                    const idx_b = try other.getBroadcastIndex(i, &b_shape);
                    c_data[i] = a_data[idx_a] - b_data[idx_b];
                }
