    pub fn subSelf(self: *Tensor, other: *Tensor) !void {
        if (self.dtype != other.dtype) return error.TypeMismatch;
        if (!self.shape.equals(&other.shape)) return error.ShapeMismatch;
        const total = self.shape.total_elements();
