    pub fn mulScalar(self: *Tensor, scalar: f64) !*Tensor {
        var result = try self.copy();
        try result.mulScalarSelf(scalar);
        return result;
    }

    pub fn mulScalarSelf(self: *Tensor, scalar: f64) !void {
        const total = self.shape.total_elements();
        switch (self.dtype) {
            .f32 => {
                var i: usize = 0;
                while (i < total) : (i += 1) self.data.f32[i] *= @floatCast(scalar);
            },
            .f64 => {
                var i: usize = 0;
                while (i < total) : (i += 1) self.data.f64[i] *= scalar;
            },
            else => return error.NotImplemented,
        }
    }

    pub fn div(self: *Tensor, other: *Tensor) !*Tensor {
        if (self.dtype != other.dtype) return error.TypeMismatch;
        var b_shape = try self.shape.broadcast(&other.shape);
        defer b_shape.deinit();
