    pub fn exp(self: *Tensor) !*Tensor {
        var result = try self.copy();
        const total = result.shape.total_elements();
        switch (self.dtype) {
            .f32 => {
                var i: usize = 0;
                while (i < total) : (i += 1) result.data.f32[i] = @exp(result.data.f32[i]);
            },
            .f64 => {
                var i: usize = 0;
                while (i < total) : (i += 1) result.data.f64[i] = @exp(result.data.f64[i]);
