    pub fn norm(self: *Tensor, p: f64) !*Tensor {
         var sum: f64 = 0.0;
         const total = self.shape.total_elements();
         switch (self.dtype) {
             .f32 => {
                 var i: usize = 0;
                 while (i < total) : (i += 1) sum += math.pow(f64, @abs(self.data.f32[i]), p);
             },
             .f64 => {
                 var i: usize = 0;
                 while (i < total) : (i += 1) sum += math.pow(f64, @abs(self.data.f64[i]), p);
             },
             else => return error.NotImplemented,
         }
         sum = math.pow(f64, sum, 1.0/p);
         var result = try init(self.allocator, &.{1}, .f64);
         result.data.f64[0] = sum;
         return result;
    }

    pub fn matmul(self: *Tensor, other: *Tensor) !*Tensor {
        if (self.shape.dims.len != 2 or other.shape.dims.len != 2) return error.InvalidShape;
        if (self.shape.dims[1] != other.shape.dims[0]) return error.DimensionMismatch;
        if (self.dtype != other.dtype) return error.TypeMismatch;

        const M = self.shape.dims[0];
        const K = self.shape.dims[1];
        const N = other.shape.dims[1];

        var result = try init(self.allocator, &.{M, N}, self.dtype);

        switch (self.dtype) {
            .f32 => {
                const a = self.data.f32;
                const b = other.data.f32;
                const c_out = result.data.f32;
                var i: usize = 0;
                while (i < M) : (i += 1) {
                    var j: usize = 0;
                    while (j < N) : (j += 1) {
                        var sum: f32 = 0.0;
                        var k: usize = 0;
                        while (k < K) : (k += 1) {
                            sum += a[i * K + k] * b[k * N + j];
                        }
                        c_out[i * N + j] = sum;
                    }
                }
            },
            .f64 => {
                const a = self.data.f64;
                const b = other.data.f64;
                const c_out = result.data.f64;
                var i: usize = 0;
                while (i < M) : (i += 1) {
                    var j: usize = 0;
                    while (j < N) : (j += 1) {
                        var sum: f64 = 0.0;
                        var k: usize = 0;
                        while (k < K) : (k += 1) {
                            sum += a[i * K + k] * b[k * N + j];
                        }
                        c_out[i * N + j] = sum;
                    }
                }
            },
             else => return error.NotImplemented,
        }
        return result;
    }

    pub fn transpose(self: *Tensor) !*Tensor {
        if (self.shape.dims.len != 2) return error.InvalidShape;
        const rows = self.shape.dims[0];
        const cols = self.shape.dims[1];
        var result = try init(self.allocator, &.{cols, rows}, self.dtype);

        switch (self.dtype) {
             .f32 => {
                 var i: usize = 0;
                 while (i < rows) : (i += 1) {
                     var j: usize = 0;
                     while (j < cols) : (j += 1) {
                         result.data.f32[j * rows + i] = self.data.f32[i * cols + j];
                     }
                 }
             },
             .f64 => {
                 var i: usize = 0;
                 while (i < rows) : (i += 1) {
                     var j: usize = 0;
                     while (j < cols) : (j += 1) {
                         result.data.f64[j * rows + i] = self.data.f64[i * cols + j];
                     }
                 }
             },
             else => return error.NotImplemented,
        }
        return result;
    }

    pub fn slice(self: *Tensor, start: usize, end: usize) !*Tensor {
        if (self.shape.dims.len != 1) return error.InvalidShape;
        if (start >= end or end > self.shape.dims[0]) return error.OutOfBounds;
        const len = end - start;
        var result = try init(self.allocator, &.{len}, self.dtype);

        switch (self.dtype) {
            .f32 => @memcpy(result.data.f32, self.data.f32[start..end]),
            .f64 => @memcpy(result.data.f64, self.data.f64[start..end]),
            else => return error.NotImplemented,
        }
        return result;
    }

    pub fn concat(self: *Tensor, other: *Tensor, dim: usize) !*Tensor {
        if (self.dtype != other.dtype) return error.TypeMismatch;
        if (self.shape.dims.len != other.shape.dims.len) return error.ShapeMismatch;
        if (dim >= self.shape.dims.len) return error.InvalidDimension;

        var new_dims = try self.allocator.alloc(usize, self.shape.dims.len);
        defer self.allocator.free(new_dims);
        @memcpy(new_dims, self.shape.dims);
        new_dims[dim] += other.shape.dims[dim];

        var result = try init(self.allocator, new_dims, self.dtype);
        const offset = self.shape.dims[dim];

        if (dim == 0 and self.shape.dims.len == 1) {
             switch (self.dtype) {
                 .f32 => {
                     @memcpy(result.data.f32[0..offset], self.data.f32);
                     @memcpy(result.data.f32[offset..], other.data.f32);
                 },
                 .f64 => {
                     @memcpy(result.data.f64[0..offset], self.data.f64);
                     @memcpy(result.data.f64[offset..], other.data.f64);
                 },
                 else => return error.NotImplemented,
             }
        } else {
            return error.NotImplemented; 
        }
        return result;
    }

    pub fn applyAstroModulation(self: *Tensor, time_ms: f64) !void {
        if (self.dtype != .f64) return error.TypeMismatch;
        var astro: f64 = 1.0 + @sin(time_ms / 1000.0 * 0.01) * 0.1;
        astro = math.clamp(astro, 0.5, 1.5);

        for (self.data.f64) |*val| {
            val.* *= astro;
        }
    }
};

