pub const ReversibleScaleFreeLayer = struct {
    weights_s: *Tensor,
    weights_t: *Tensor,
    bias_s: *Tensor,
    bias_t: *Tensor,
    allocator: Allocator,

    pub fn init(allocator: Allocator, size: usize) !*ReversibleScaleFreeLayer {
        var layer = try allocator.create(ReversibleScaleFreeLayer);
        const half = size / 2;
        layer.weights_s = try Tensor.randomNormal(allocator, &.{half, half}, .f64, 0.0, 0.02, 0);
        layer.weights_t = try Tensor.randomNormal(allocator, &.{half, half}, .f64, 0.0, 0.02, 1);
        layer.bias_s = try Tensor.zeros(allocator, &.{half}, .f64);
        layer.bias_t = try Tensor.zeros(allocator, &.{half}, .f64);
        layer.allocator = allocator;
        return layer;
    }

    pub fn deinit(self: *ReversibleScaleFreeLayer) void {
        self.weights_s.deinit();
        self.weights_t.deinit();
        self.bias_s.deinit();
        self.bias_t.deinit();
        self.allocator.destroy(self);
    }

    pub fn forward(self: *ReversibleScaleFreeLayer, input: *Tensor) !*Tensor {
        if (input.shape.dims.len != 1 or input.shape.dims[0] % 2 != 0) return error.InvalidInput;
        const half = input.shape.dims[0] / 2;
        var x1 = try input.slice(0, half);
        defer x1.deinit();
        var x2 = try input.slice(half, input.shape.dims[0]);
        defer x2.deinit();
        var s_x2 = try self.weights_s.matmul(x2);
        defer s_x2.deinit();
        s_x2 = try s_x2.add(self.bias_s);
        var exp_s_x2 = try s_x2.exp();
        defer exp_s_x2.deinit();
        var y1 = try x1.mul(exp_s_x2);

        try y1.applyAstroModulation(100.0);

        var t_y1 = try self.weights_t.matmul(y1);
        defer t_y1.deinit();
        t_y1 = try t_y1.add(self.bias_t);
        var y2 = try x2.add(t_y1);
        return try y1.concat(y2, 0);
    }

    pub fn backward(self: *ReversibleScaleFreeLayer, y: *Tensor, grad_y: *Tensor) !*Tensor {
        const half = grad_y.shape.dims[0] / 2;
        var y1 = try y.slice(0, half);
        defer y1.deinit();
        var y2 = try y.slice(half, y.shape.dims[0]);
        defer y2.deinit();
        var gy1 = try grad_y.slice(0, half);
        defer gy1.deinit();
        var gy2 = try grad_y.slice(half, grad_y.shape.dims[0]);
        defer gy2.deinit();
        var t_y1 = try self.weights_t.matmul(y1);
        defer t_y1.deinit();
        t_y1 = try t_y1.add(self.bias_t);
        var x2 = try y2.sub(t_y1);
        defer x2.deinit();
        var s_x2 = try self.weights_s.matmul(x2);
        defer s_x2.deinit();
        s_x2 = try s_x2.add(self.bias_s);
        var exp_s_x2 = try s_x2.exp();
        defer exp_s_x2.deinit();
        var gt_y1 = gy2;
        var gy1_wt = try self.weights_t.transpose().matmul(gt_y1);
        defer gy1_wt.deinit();
        gy1 = try gy1.add(gy1_wt);
        var gs_x2 = try gy1.mul(y1);
        defer gs_x2.deinit();
        var gx1 = try gy1.mul(exp_s_x2);
        var gx2_s = try self.weights_s.transpose().matmul(gs_x2);
        defer gx2_s.deinit();
        var gx2 = try gy2.add(gx2_s);
        return try gx1.concat(gx2, 0);
    }

    pub fn inverse(self: *ReversibleScaleFreeLayer, y: *Tensor) !*Tensor {
        const half = y.shape.dims[0] / 2;
        var y1 = try y.slice(0, half);
        defer y1.deinit();
        var y2 = try y.slice(half, y.shape.dims[0]);
        defer y2.deinit();
        var t_y1 = try self.weights_t.matmul(y1);
        defer t_y1.deinit();
        t_y1 = try t_y1.add(self.bias_t);
        var x2 = try y2.sub(t_y1);
        defer x2.deinit();
        var s_x2 = try self.weights_s.matmul(x2);
        defer s_x2.deinit();
        s_x2 = try s_x2.add(self.bias_s);
        var exp_s_x2 = try s_x2.exp();
        defer exp_s_x2.deinit();
        var x1 = try y1.div(exp_s_x2);
        return try x1.concat(x2, 0);
    }
};

pub const RSFProcessor = struct {
    config: RSFConfig,
    allocator: Allocator,
    layers: []*ReversibleScaleFreeLayer,

    pub fn init(allocator: Allocator, config: RSFConfig) !*RSFProcessor {
        var proc = try allocator.create(RSFProcessor);
        proc.config = config;
        proc.allocator = allocator;
        proc.layers = try allocator.alloc(*ReversibleScaleFreeLayer, config.num_layers);
        var i: usize = 0;
        while (i < config.num_layers) : (i += 1) {
            proc.layers[i] = try ReversibleScaleFreeLayer.init(allocator, config.hidden_size);
        }
        return proc;
    }

    pub fn deinit(self: *RSFProcessor) void {
        for (self.layers) |layer| {
            layer.deinit();
        }
        self.allocator.free(self.layers);
        self.allocator.destroy(self);
    }

    pub fn forward(self: *RSFProcessor, input: *Tensor) !*Tensor {
        var current = try input.copy();
        defer current.deinit();
        for (self.layers) |layer| {
            var next = try layer.forward(current);
            current.deinit();
            current = next;
        }
        return current;
    }

    pub fn backward(self: *RSFProcessor, output: *Tensor, grad_output: *Tensor) !*Tensor {
        var current = try output.copy();
        var current_grad = try grad_output.copy();
        var i: isize = @intCast(self.layers.len - 1);
        while (i >= 0) : (i -= 1) {
            var next_grad = try self.layers[@intCast(i)].backward(current, current_grad);
            current_grad.deinit();
            current_grad = next_grad;
            var next = try self.layers[@intCast(i)].inverse(current);
            current.deinit();
            current = next;
        }
        current.deinit();
        return current_grad;
    }
};

pub const SFDConfig = struct {
    learning_rate: f64 = 0.001,
    momentum: f64 = 0.9,
    dampening: f64 = 0.0,
    nesterov: bool = false,
    weight_decay: f64 = 0.0,
    clip_norm: f64 = 0.0,
};

pub const StochasticFisherDescent = struct {
    config: SFDConfig,
    allocator: Allocator,
    params: std.ArrayList(*Tensor),
    velocities: std.ArrayList(*Tensor),
    fisher_info: std.ArrayList(*Tensor),

    pub fn init(allocator: Allocator, config: SFDConfig) !*StochasticFisherDescent {
        var sfd = try allocator.create(StochasticFisherDescent);
        sfd.* = .{
            .config = config,
            .allocator = allocator,
            .params = std.ArrayList(*Tensor).init(allocator),
            .velocities = std.ArrayList(*Tensor).init(allocator),
            .fisher_info = std.ArrayList(*Tensor).init(allocator),
        };
        return sfd;
    }

    pub fn deinit(self: *StochasticFisherDescent) void {
        for (self.velocities.items) |v| v.deinit();
        self.velocities.deinit();
        for (self.fisher_info.items) |f| f.deinit();
        self.fisher_info.deinit();
        self.params.deinit();
        self.allocator.destroy(self);
    }

    pub fn addParam(self: *StochasticFisherDescent, param: *Tensor) !void {
        param.requires_grad = true;
        try self.params.append(param);
        var velocity = try Tensor.zeros(self.allocator, param.shape.dims, param.dtype);
        try self.velocities.append(velocity);
        var fisher = try Tensor.ones(self.allocator, param.shape.dims, param.dtype);
        try self.fisher_info.append(fisher);
    }

    pub fn zeroGrad(self: *StochasticFisherDescent) void {
        for (self.params.items) |p| {
            if (p.grad) |g| {
                switch (g.dtype) {
                    .f32 => @memset(g.data.f32, 0.0),
                    .f64 => @memset(g.data.f64, 0.0),
                    .i32 => @memset(g.data.i32, 0),
                    .u32 => @memset(g.data.u32, 0),
                    .c64 => @memset(g.data.c64, .{ .re = 0.0, .im = 0.0 }),
                    .bool => @memset(g.data.bool, false),
                }
            }
        }
    }

    pub fn step(self: *StochasticFisherDescent) !void {
        var i: usize = 0;
        while (i < self.params.items.len) : (i += 1) {
            const param = self.params.items[i];
            const velocity = self.velocities.items[i];
            const fisher = self.fisher_info.items[i];
            if (param.grad) |grad| {
                var g = try grad.copy();
                defer g.deinit();
                if (self.config.weight_decay != 0.0) {
                    var wd = try param.mulScalar(self.config.weight_decay);
                    defer wd.deinit();
                    try g.addSelf(wd);
                }
                if (self.config.clip_norm > 0.0) {
                    const norm = try g.norm(2);
                    defer norm.deinit();
                    if (norm.data.f64[0] > self.config.clip_norm) {
                        try g.mulScalarSelf(self.config.clip_norm / norm.data.f64[0]);
                    }
                }
                var natural_grad = try g.div(fisher);
                defer natural_grad.deinit();
                if (self.config.momentum != 0.0) {
                    if (self.config.nesterov) {
                        var mom_g = try natural_grad.mulScalar(self.config.momentum);
                        defer mom_g.deinit();
                        try velocity.addSelf(mom_g);
                        var update = try velocity.copy();
                        defer update.deinit();
                        try update.mulScalarSelf(self.config.momentum);
                        try update.addSelf(natural_grad);
                        try param.subSelf(update);
                    } else {
                        try velocity.mulScalarSelf(self.config.momentum);
                        try velocity.addSelf(natural_grad);
                        var update = try velocity.copy();
                        defer update.deinit();
                        try update.mulScalarSelf(self.config.learning_rate);
                        try param.subSelf(update);
                    }
                } else {
                    var update = try natural_grad.mulScalar(self.config.learning_rate);
                    defer update.deinit();
                    try param.subSelf(update);
                }
                var g_sq = try g.mul(g);
                defer g_sq.deinit();
                var new_fisher = try fisher.copy();
                try new_fisher.mulScalarSelf(0.99);
                var add_g_sq = try g_sq.mulScalar(0.01);
                defer add_g_sq.deinit();
                try new_fisher.addSelf(add_g_sq);
                fisher.deinit();
                fisher.* = new_fisher.*;
                self.allocator.destroy(new_fisher);
            }
        }
    }
};

pub const MGTConfig = struct {
    vocab_size: usize = 50257,
    max_tokens: usize = 2048,
    merge_threshold: f64 = 0.1,
};

pub const MergePair = struct {
    a: u32,
    b: u32,
    freq: u32,
};

pub const MergeableGraphTokenizer = struct {
    config: MGTConfig,
    allocator: Allocator,
    vocab: HashMap([]const u8, u32, std.hash_map.StringContext, 80),
    reverse: HashMap(u32, []const u8, std.hash_map.AutoContext(u32), 80),
    merges: ArrayList(MergePair),

    pub fn init(allocator: Allocator, config: MGTConfig) !*MergeableGraphTokenizer {
        var tokenizer = try allocator.create(MergeableGraphTokenizer);
        tokenizer.* = .{
            .config = config,
            .allocator = allocator,
            .vocab = HashMap([]const u8, u32, std.hash_map.StringContext, 80).init(allocator),
            .reverse = HashMap(u32, []const u8, std.hash_map.AutoContext(u32), 80).init(allocator),
            .merges = ArrayList(MergePair).init(allocator),
        };
        var i: u32 = 0;
        while (i < 256) : (i += 1) {
            var byte = try allocator.alloc(u8, 1);
            byte[0] = @intCast(i);
            try tokenizer.vocab.put(byte, i);
            try tokenizer.reverse.put(i, byte);
        }
        return tokenizer;
    }

    pub fn deinit(self: *MergeableGraphTokenizer) void {
        var it = self.vocab.iterator();
        while (it.next()) |entry| {
            self.allocator.free(entry.key_ptr.*);
        }
        self.vocab.deinit();
        self.reverse.deinit();
        self.merges.deinit();
        self.allocator.destroy(self);
    }

    pub fn train(self: *MergeableGraphTokenizer, corpus: []const u8, iterations: usize) !void {
        var freq = HashMap(MergePair, u32, std.hash_map.AutoContext(MergePair), 80).init(self.allocator);
        defer freq.deinit();
        var i: usize = 0;
        while (i < corpus.len - 1) : (i += 1) {
            const pair = MergePair{ .a = @intCast(corpus[i]), .b = @intCast(corpus[i + 1]), .freq = 0 };
            var count = try freq.getOrPut(pair);
            count.value_ptr.* += 1;
        }
        var iter: usize = 0;
        while (iter < iterations and self.vocab.count() < self.config.vocab_size) : (iter += 1) {
            var max_freq: u32 = 0;
            var best_pair: ?MergePair = null;
            var fit = freq.iterator();
            while (fit.next()) |entry| {
                if (entry.value_ptr.* > max_freq) {
                    max_freq = entry.value_ptr.*;
                    best_pair = entry.key_ptr.*;
                }
            }
            if (best_pair) |pair| {
                if (max_freq < self.config.merge_threshold * @as(f64, @floatFromInt(corpus.len))) continue;
                try self.merges.append(pair);
                const new_token = @as(u32, @intCast(self.vocab.count()));
                const sym_a = self.reverse.get(pair.a) orelse return error.MissingSymbol;
                const sym_b = self.reverse.get(pair.b) orelse return error.MissingSymbol;
                var new_sym = try self.allocator.alloc(u8, sym_a.len + sym_b.len);
                @memcpy(new_sym[0..sym_a.len], sym_a);
                @memcpy(new_sym[sym_a.len..], sym_b);
                try self.vocab.put(new_sym, new_token);
                try self.reverse.put(new_token, new_sym);
                var new_freq = HashMap(MergePair, u32, std.hash_map.AutoContext(MergePair), 80).init(self.allocator);
                defer new_freq.deinit();
                var j: usize = 0;
                while (j < corpus.len - 1) : (j += 1) {
                    if (corpus[j] == pair.a and corpus[j + 1] == pair.b) {
                        if (j > 0) {
                            const prev_pair = MergePair{ .a = @intCast(corpus[j - 1]), .b = new_token, .freq = 0 };
                            var count = try new_freq.getOrPut(prev_pair);
                            count.value_ptr.* += 1;
                        }
                        if (j < corpus.len - 2) {
                            const next_pair = MergePair{ .a = new_token, .b = @intCast(corpus[j + 2]), .freq = 0 };
                            var count = try new_freq.getOrPut(next_pair);
                            count.value_ptr.* += 1;
                        }
                        j += 1;
                    } else {
                        const curr_pair = MergePair{ .a = @intCast(corpus[j]), .b = @intCast(corpus[j + 1]), .freq = 0 };
                        var count = try new_freq.getOrPut(curr_pair);
                        count.value_ptr.* += 1;
                    }
                }
                freq.clearRetainingCapacity();
                var nit = new_freq.iterator();
                while (nit.next()) |entry| {
                    try freq.put(entry.key_ptr.*, entry.value_ptr.*);
                }
            } else {
                break;
            }
        }
    }

    pub fn tokenize(self: *MergeableGraphTokenizer, text: []const u8) ![]u32 {
        var tokens = ArrayList(u32).init(self.allocator);
        errdefer tokens.deinit();
        var i: usize = 0;
        while (i < text.len) : (i += 1) {
            try tokens.append(@intCast(text[i]));
        }
        for (self.merges.items, 0..) |merge, idx| {
            const token = 256 + @as(u32, @intCast(idx));
            i = 0;
            while (i < tokens.items.len - 1) {
                if (tokens.items[i] == merge.a and tokens.items[i + 1] == merge.b) {
                    tokens.items[i] = token;
                    _ = tokens.orderedRemove(i + 1);
                } else {
                    i += 1;
                }
            }
        }
        return tokens.toOwnedSlice();
    }

    pub fn detokenize(self: *MergeableGraphTokenizer, tokens: []const u32) ![]u8 {
        var text = ArrayList(u8).init(self.allocator);
        errdefer text.deinit();
        for (tokens) |tok| {
            if (self.reverse.get(tok)) |sym| {
                try text.appendSlice(sym);
            }
        }
        return text.toOwnedSlice();
    }
};

